# Baseline results from the task description:
baseline = {
    'b1': {'cost': 2.4830e+12, 'pad_ratio': 1.4363, 'p95': 1.3157e+07, 'seq': 4.8973e+07},
    'b2': {'cost': 1.6673e+12, 'pad_ratio': 4.0430, 'p95': 3.4104e+06, 'seq': 1.1463e+07}
}

# Thresholds from the task description:
thresholds = {
    'b1': {'cost': 3.0e11, 'pad_ratio': 0.055, 'p95': 2.1e6, 'seq': 2.7e8},
    'b2': {'cost': 4.8e10, 'pad_ratio': 0.15, 'p95': 2.1e5, 'seq': 3.2e7}
}

print("Comparison with thresholds:")
for bucket, data in baseline.items():
    print(f"\n{bucket.upper()}:")
    for metric, baseline_val in data.items():
        threshold_val = thresholds[bucket][metric]
        ratio = baseline_val / threshold_val if threshold_val > 0 else 0
        status = "PASS" if baseline_val < threshold_val else "FAIL"
        print(f"  {metric:15s}: {baseline_val:.4e} (threshold: {threshold_val:.4e}) - {status} ({ratio:.2f}x)")
EOF
